		t.Fatalf("Add after restart failed: %v", err)
	}

	if addResult.ID != 3 {
		t.Errorf("Expected next ID to be 3 after restart, got %d", addResult.ID)
	}
}





















































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































