	err := ioutil.WriteFile(tasksFile, []byte("[]"), 0644)
	if err != nil {
		t.Fatalf("Failed to clear tasks file: %v", err)
	}
	nextID = 1 // Reset nextID for consistent test results

	Add("Buy groceries") // ID should be 1
